        "scene": "",
        "dialogues": [
          "秦淮河畔烏衣巷那群秦淮惡少悍徒，在下早想去會會了，只是另有要事，不便多管。",
          "練武之人，最怕的不是敵人，是自己心浮氣躁。",
          "別看我現在落魄，當年在漢中府，也算是有些名號的。",
          "劍是死的，人是活的。招式再精妙，用不對時機也是白搭。",
          "「天下武功，唯快不破」——這話我只信一半。",
          "若有機會，真想去通天塔闖一闖，看看自己究竟有幾斤幾兩。"
        ],
        "attackable": false,
        "reactWin": [
          "方才那一下變招，妙！妙極！",
          "痛快！看得我也手癢了。",
          "這一戰，夠我回去喝三壺酒了。",
          "出手乾淨利落，兄台他日必成大器。",
          "好功夫！在下佩服。"
        ],
        "reactLose": [
          "輸一次不算什麼，在下當年輸得比你還慘。",
          "別灰心，能爬起來的才是真俠客。",
          "那人下盤很穩，不妨攻他身法弱處。",
          "兄台方才出手太急，下回沉住氣再戰。",
          "養好了傷再來，江湖路長得很。"
        ]
