          "閩江古渡一帶，是我說了算。官府？官府也得給我三分薄面。",
          "年輕人，想出名？踩著我上位倒是條捷徑——就怕你沒那本事。",
          "有膽識，我欣賞你。要不要跟著我幹？吃香喝辣少不了你的。",
          "別擋著我的道。今天心情好，不想見血。",
          "我手下那群廢物不中用，倒要看看你有多少斤兩。"
