        "desc": "盤踞邙山古墓道、手底頗硬的頭目。",
        "scene": "fight_洛陽城",
        "dialogues": [
          "別擋著我的道。今天心情好，不想見血。",
          "我手下那群廢物不中用，倒要看看你有多少斤兩。",
          "邙山古墓道一帶，是我說了算。官府？官府也得給我三分薄面。",
          "有膽識，我欣賞你。要不要跟著我幹？吃香喝辣少不了你的。",
          "我當年也是名門正派出身，後來嘛……江湖就是這樣。",
          "年輕人，想出名？踩著我上位倒是條捷徑——就怕你沒那本事。"
        ],
        "attackable": true,
        "realm": "出神入化",
