          "想拜入武當派？請先往紫霄大殿拜見掌門，學武則到太和傳功殿找宋遠橋。",
          "山路險峻，一路上可還順利？",
          "本派門規森嚴，入門之後切莫違犯，否則逐出師門可不是說笑的。",
          "掌門張三丰今日在紫霄大殿，若有要事，可前去求見。",
