  "少林寺・大雄寶殿": {
    "name": "少林寺・大雄寶殿",
    "area": "少林寺",
    "sect": "少林寺",
    "desc": "少林寺的核心所在，掌門平日在此主持門務。",
    "grid": [
      0,
      2
    ],
    "exits": {
      "south": "少林寺・練武場",
      "west": "少林寺・藏經閣",
      "east": "少林寺・達摩院",
      "north": "少林寺・後山塔林"
    },
    "scenes": [],
    "npcs": [
      {
        "id": "少林寺_leader",
        "name": "方丈 玄慈大師",
        "desc": "少林寺當代掌門。長老以上的弟子可向其挑戰出師。",
        "scene": "",
        "attackable": false,
        "service": "sect_hall",
        "dialogues": [
          "你來了。",
          "少林寺立派至今，靠的不是武功高強，而是門下弟子心正。",
          "江湖風波惡，望你行事三思而後行。",
          "若你有朝一日能勝過我，便可出師下山，自立門戶。",
          "我看你眼中有股傲氣——是好事，也是壞事。",
          "練武先練心，心不正，武功越高越是禍害。"
        ],
        "reactWin": [
          "好身手！",
          "這一戰打得漂亮。",
          "師兄輸得不冤。",
          "看來今天又有新的高手了。",
          "精彩，精彩！"
        ],
        "reactLose": [
          "勝敗乃兵家常事。",
          "下回再戰便是。",
          "別氣餒，再練練。",
          "受傷了嗎？快去歇息。",
          "輸給師兄不丟人。"
        ]
      }
    ]
  },
  "少林寺・藏經閣": {
    "name": "少林寺・藏經閣",
    "area": "少林寺",
    "sect": "少林寺",
    "desc": "收藏本派歷代秘笈的重地，戒備森嚴。",
    "grid": [
      -1,
      2
    ],
    "exits": {
      "east": "少林寺・大雄寶殿"
    },
    "scenes": [],
    "npcs": [
      {
        "id": "少林寺_librarian",
        "name": "守閣弟子",
        "desc": "看守藏經閣的弟子，一絲不苟。",
        "scene": "",
        "attackable": false,
        "dialogues": [
          "藏經閣重地，閒人免進。",
          "閣中秘笈，非真傳弟子不得翻閱。",
          "噓——小聲些，長老們在裡面參悟心法。",
          "這裡的每一本書，都是前輩們用血汗換來的。",
          "你若真想看書，先在門中立下功勞再說。"
        ]
      }
    ]
  },
  "少林寺・達摩院": {
    "name": "少林寺・達摩院",
    "area": "少林寺",
    "sect": "少林寺",
    "desc": "傳功長老在此傳授武學、考校弟子的功課。",
    "grid": [
      1,
      2
    ],
    "exits": {
      "west": "少林寺・大雄寶殿"
    },
    "scenes": [
      {
        "id": "sect_少林寺_hall",
        "name": "傳功大殿",
        "type": "sect",
        "sectName": "少林寺",
        "desc": "拜入少林寺、請教武學、晉升門階、領取例銀。"
      }
    ],
    "npcs": [
      {
        "id": "少林寺_elder",
        "name": "達摩院首座 玄苦大師",
        "desc": "少林寺負責傳授武學的長輩。",
        "scene": "",
        "attackable": false,
        "service": "sect_hall",
        "dialogues": [
          "本派武學浩瀚，貪多嚼不爛，練精一門再學下一門。",
          "你的根骨還算可以，就看肯不肯下苦功了。",
          "武學一道，三分天資，七分苦練。",
          "想學高深武學，先把門階提升上來，這是規矩。",
          "當年我學這套功夫，整整花了十年。你們這些年輕人啊，太急了。",
          "有不懂的，儘管來問。"
        ]
      }
    ]
  },
  "少林寺・後山塔林": {
    "name": "少林寺・後山塔林",
    "area": "少林寺",
    "sect": "少林寺",
    "desc": "人跡罕至的僻靜之處，據說有前輩在此隱居。",
    "grid": [
      0,
      3
    ],
    "exits": {
      "south": "少林寺・大雄寶殿"
    },
    "scenes": [],
    "npcs": [
      {
        "id": "少林寺_hermit",
        "name": "隱世前輩",
        "desc": "鬚髮皆白的老者，看不出年紀與武功深淺。",
        "scene": "",
        "attackable": false,
        "dialogues": [
          "……年輕人，這裡很少有人來。",
          "我在這兒住了三十年，看雲起雲落，倒也自在。",
          "武功練到最後，不過是一個「心」字。",
          "下山去吧，江湖需要你這樣的人。",
          "老夫早已不問世事，莫要擾我清修。",
          "你身上的殺氣太重了，坐下來，陪我看看雲吧。"
        ]
      }
    ]
  },
