  "金刀門・金刀堂": {
    "name": "金刀門・金刀堂",
    "area": "金刀門",
    "sect": "金刀門",
    "desc": "金刀門的核心所在，掌門平日在此主持門務。",
    "grid": [
      0,
      2
    ],
    "exits": {
      "south": "金刀門・演武院",
      "west": "金刀門・兵器庫",
      "east": "金刀門・傳藝廳",
      "north": "金刀門・王府後花園"
    },
    "scenes": [],
    "npcs": [
      {
        "id": "金刀門_leader",
        "name": "門主 王元霸",
        "desc": "金刀門當代掌門。長老以上的弟子可向其挑戰出師。",
        "scene": "",
        "attackable": false,
        "service": "sect_hall",
        "dialogues": [
          "你來了。",
          "金刀門立派至今，靠的不是武功高強，而是門下弟子心正。",
          "江湖風波惡，望你行事三思而後行。",
          "若你有朝一日能勝過我，便可出師下山，自立門戶。",
          "我看你眼中有股傲氣——是好事，也是壞事。",
          "練武先練心，心不正，武功越高越是禍害。"
        ],
        "reactWin": [
          "好身手！",
          "這一戰打得漂亮。",
          "師兄輸得不冤。",
          "看來今天又有新的高手了。",
          "精彩，精彩！"
        ],
        "reactLose": [
          "勝敗乃兵家常事。",
          "下回再戰便是。",
          "別氣餒，再練練。",
          "受傷了嗎？快去歇息。",
          "輸給師兄不丟人。"
        ]
      }
    ]
  },
  "金刀門・兵器庫": {
    "name": "金刀門・兵器庫",
    "area": "金刀門",
    "sect": "金刀門",
    "desc": "收藏本派歷代秘笈的重地，戒備森嚴。",
    "grid": [
      -1,
      2
    ],
    "exits": {
      "east": "金刀門・金刀堂"
    },
    "scenes": [],
    "npcs": [
      {
        "id": "金刀門_librarian",
        "name": "守閣弟子",
        "desc": "看守兵器庫的弟子，一絲不苟。",
        "scene": "",
        "attackable": false,
        "dialogues": [
          "兵器庫重地，閒人免進。",
          "閣中秘笈，非真傳弟子不得翻閱。",
          "噓——小聲些，長老們在裡面參悟心法。",
          "這裡的每一本書，都是前輩們用血汗換來的。",
          "你若真想看書，先在門中立下功勞再說。"
        ]
      }
    ]
  },
  "金刀門・傳藝廳": {
    "name": "金刀門・傳藝廳",
    "area": "金刀門",
    "sect": "金刀門",
    "desc": "傳功長老在此傳授武學、考校弟子的功課。",
    "grid": [
      1,
      2
    ],
    "exits": {
      "west": "金刀門・金刀堂"
    },
    "scenes": [
      {
        "id": "sect_金刀門_hall",
        "name": "傳功大殿",
        "type": "sect",
        "sectName": "金刀門",
        "desc": "拜入金刀門、請教武學、晉升門階、領取例銀。"
      }
    ],
    "npcs": [
      {
        "id": "金刀門_elder",
        "name": "傳功教頭 王伯奮",
        "desc": "金刀門負責傳授武學的長輩。",
        "scene": "",
        "attackable": false,
        "service": "sect_hall",
        "dialogues": [
          "本派武學浩瀚，貪多嚼不爛，練精一門再學下一門。",
          "你的根骨還算可以，就看肯不肯下苦功了。",
          "武學一道，三分天資，七分苦練。",
          "想學高深武學，先把門階提升上來，這是規矩。",
          "當年我學這套功夫，整整花了十年。你們這些年輕人啊，太急了。",
          "有不懂的，儘管來問。"
        ]
      }
    ]
  },
  "金刀門・王府後花園": {
    "name": "金刀門・王府後花園",
    "area": "金刀門",
    "sect": "金刀門",
    "desc": "人跡罕至的僻靜之處，據說有前輩在此隱居。",
    "grid": [
      0,
      3
    ],
    "exits": {
      "south": "金刀門・金刀堂"
    },
    "scenes": [],
    "npcs": [
      {
        "id": "金刀門_hermit",
        "name": "隱世前輩",
        "desc": "鬚髮皆白的老者，看不出年紀與武功深淺。",
        "scene": "",
        "attackable": false,
        "dialogues": [
          "……年輕人，這裡很少有人來。",
          "我在這兒住了三十年，看雲起雲落，倒也自在。",
          "武功練到最後，不過是一個「心」字。",
          "下山去吧，江湖需要你這樣的人。",
          "老夫早已不問世事，莫要擾我清修。",
          "你身上的殺氣太重了，坐下來，陪我看看雲吧。"
        ]
      }
    ]
  },
  "南拳門・武館大門": {
    "name": "南拳門・武館大門",
    "area": "南拳門",
    "sect": "南拳門",
    "desc": "南拳門的門面。來往的香客與拜師者都要先在此通報。",
    "grid": [
      0,
      0
    ],
    "exits": {
      "north": "南拳門・木人樁陣"
    },
    "scenes": [
      {
        "id": "gate_南拳門_out",
        "name": "下山返回佛山鎮",
        "type": "gate",
        "target": "佛山鎮",
        "desc": "沿山路下行，返回佛山鎮。"
      }
    ],
    "npcs": [
      {
        "id": "南拳門_greeter",
        "name": "迎客弟子",
        "desc": "在武館大門迎送賓客的年輕弟子。",
        "scene": "",
        "attackable": false,
        "service": "sect_hall",
        "dialogues": [
          "施主遠道而來，辛苦了。這裡是南拳門，請隨意參觀，莫要喧嘩。",
          "想拜入南拳門？請先往南拳正廳拜見掌門，學武則到傳功房找梁贊師傅。",
          "山路險峻，一路上可還順利？",
          "本派門規森嚴，入門之後切莫違犯，否則逐出師門可不是說笑的。",
          "掌門黃飛鴻今日在南拳正廳，若有要事，可前去求見。",
          "我入門才三年，還只是個看門的……師兄們都說，要耐得住性子。"
        ],
        "reactWin": [
          "好身手！",
          "這一戰打得漂亮。",
          "師兄輸得不冤。",
          "看來今天又有新的高手了。",
          "精彩，精彩！"
        ],
        "reactLose": [
          "勝敗乃兵家常事。",
          "下回再戰便是。",
          "別氣餒，再練練。",
          "受傷了嗎？快去歇息。",
          "輸給師兄不丟人。"
        ]
      }
    ]
  },
