  "北腿宗・常山門樓": {
    "name": "北腿宗・常山門樓",
    "area": "北腿宗",
    "sect": "北腿宗",
    "desc": "北腿宗的門面。來往的香客與拜師者都要先在此通報。",
    "grid": [
      0,
      0
    ],
    "exits": {
      "north": "北腿宗・踢樁場"
    },
    "scenes": [
      {
        "id": "gate_北腿宗_out",
        "name": "下山返回真定府",
        "type": "gate",
        "target": "真定府",
        "desc": "沿山路下行，返回真定府。"
      }
    ],
    "npcs": [
      {
        "id": "北腿宗_greeter",
        "name": "迎客弟子",
        "desc": "在常山門樓迎送賓客的年輕弟子。",
        "scene": "",
        "attackable": false,
        "service": "sect_hall",
        "dialogues": [
          "施主遠道而來，辛苦了。這裡是北腿宗，請隨意參觀，莫要喧嘩。",
          "想拜入北腿宗？請先往北腿正堂拜見掌門，學武則到傳功堂找譚腿老怪。",
          "山路險峻，一路上可還順利？",
          "本派門規森嚴，入門之後切莫違犯，否則逐出師門可不是說笑的。",
          "掌門燕青神腿今日在北腿正堂，若有要事，可前去求見。",
          "我入門才三年，還只是個看門的……師兄們都說，要耐得住性子。"
        ],
        "reactWin": [
          "好身手！",
          "這一戰打得漂亮。",
          "師兄輸得不冤。",
          "看來今天又有新的高手了。",
          "精彩，精彩！"
        ],
        "reactLose": [
          "勝敗乃兵家常事。",
          "下回再戰便是。",
          "別氣餒，再練練。",
          "受傷了嗎？快去歇息。",
          "輸給師兄不丟人。"
        ]
      }
    ]
  },
