  "一刀流道館・本願道場正殿": {
    "name": "一刀流道館・本願道場正殿",
    "area": "一刀流道館",
    "sect": "一刀流道館",
    "desc": "一刀流道館的核心所在，掌門平日在此主持門務。",
    "grid": [
      0,
      2
    ],
    "exits": {
      "south": "一刀流道館・庭院試刀場",
      "west": "一刀流道館・秘傳書庫",
      "east": "一刀流道館・師範房",
      "north": "一刀流道館・後山竹林"
    },
    "scenes": [],
    "npcs": [
      {
        "id": "一刀流_leader",
        "name": "居合劍聖 伊東一刀齋",
        "desc": "一刀流道館當代掌門。長老以上的弟子可向其挑戰出師。",
        "scene": "",
        "attackable": false,
        "service": "sect_hall",
        "dialogues": [
          "你來了。",
          "一刀流道館立派至今，靠的不是武功高強，而是門下弟子心正。",
          "江湖風波惡，望你行事三思而後行。",
          "若你有朝一日能勝過我，便可出師下山，自立門戶。",
          "我看你眼中有股傲氣——是好事，也是壞事。",
          "練武先練心，心不正，武功越高越是禍害。"
        ],
        "reactWin": [
          "好身手！",
          "這一戰打得漂亮。",
          "師兄輸得不冤。",
          "看來今天又有新的高手了。",
          "精彩，精彩！"
        ],
        "reactLose": [
          "勝敗乃兵家常事。",
          "下回再戰便是。",
          "別氣餒，再練練。",
          "受傷了嗎？快去歇息。",
          "輸給師兄不丟人。"
        ]
      }
    ]
  },
  "一刀流道館・秘傳書庫": {
    "name": "一刀流道館・秘傳書庫",
    "area": "一刀流道館",
    "sect": "一刀流道館",
    "desc": "收藏本派歷代秘笈的重地，戒備森嚴。",
    "grid": [
      -1,
      2
    ],
    "exits": {
      "east": "一刀流道館・本願道場正殿"
    },
    "scenes": [],
    "npcs": [
      {
        "id": "一刀流_librarian",
        "name": "守閣弟子",
        "desc": "看守秘傳書庫的弟子，一絲不苟。",
        "scene": "",
        "attackable": false,
        "dialogues": [
          "秘傳書庫重地，閒人免進。",
          "閣中秘笈，非真傳弟子不得翻閱。",
          "噓——小聲些，長老們在裡面參悟心法。",
          "這裡的每一本書，都是前輩們用血汗換來的。",
          "你若真想看書，先在門中立下功勞再說。"
        ]
      }
    ]
  },
  "一刀流道館・師範房": {
    "name": "一刀流道館・師範房",
    "area": "一刀流道館",
    "sect": "一刀流道館",
    "desc": "傳功長老在此傳授武學、考校弟子的功課。",
    "grid": [
      1,
      2
    ],
    "exits": {
      "west": "一刀流道館・本願道場正殿"
    },
    "scenes": [
      {
        "id": "sect_一刀流_hall",
        "name": "傳功大殿",
        "type": "sect",
        "sectName": "一刀流道館",
        "desc": "拜入一刀流道館、請教武學、晉升門階、領取例銀。"
      }
    ],
    "npcs": [
      {
        "id": "一刀流_elder",
        "name": "傳功師範 柳生嚴包",
        "desc": "一刀流道館負責傳授武學的長輩。",
        "scene": "",
        "attackable": false,
        "service": "sect_hall",
        "dialogues": [
          "本派武學浩瀚，貪多嚼不爛，練精一門再學下一門。",
          "你的根骨還算可以，就看肯不肯下苦功了。",
          "武學一道，三分天資，七分苦練。",
          "想學高深武學，先把門階提升上來，這是規矩。",
          "當年我學這套功夫，整整花了十年。你們這些年輕人啊，太急了。",
          "有不懂的，儘管來問。"
        ]
      }
    ]
  },
  "一刀流道館・後山竹林": {
    "name": "一刀流道館・後山竹林",
    "area": "一刀流道館",
    "sect": "一刀流道館",
    "desc": "人跡罕至的僻靜之處，據說有前輩在此隱居。",
    "grid": [
      0,
      3
    ],
    "exits": {
      "south": "一刀流道館・本願道場正殿"
    },
    "scenes": [],
    "npcs": [
      {
        "id": "一刀流_hermit",
        "name": "隱世前輩",
        "desc": "鬚髮皆白的老者，看不出年紀與武功深淺。",
        "scene": "",
        "attackable": false,
        "dialogues": [
          "……年輕人，這裡很少有人來。",
          "我在這兒住了三十年，看雲起雲落，倒也自在。",
          "武功練到最後，不過是一個「心」字。",
          "下山去吧，江湖需要你這樣的人。",
          "老夫早已不問世事，莫要擾我清修。",
          "你身上的殺氣太重了，坐下來，陪我看看雲吧。"
        ]
      }
    ]
  },
