          "敵軍雖兇，若用「鴛鴦陣」法，長短相救，敵雖千騎亦奈何不得。",
          "兵者詭道，然治軍以誠，方能令行禁止。",
          "閣下若能通過本帥的考驗，這部《紀效新書》便贈予你又何妨。"
